import Foundation

/// Places the hyphens of an ISBN-13 by the International ISBN Agency's ranges
/// (`ISBNRanges`, generated by `make isbn-ranges`). The positions depend on the
/// registration group and the publisher, so no fixed pattern fits:
/// 978-0-306-40615-7, but 978-3-15-011537-4.
struct ISBNHyphenation: Sendable {
    /// A 7-digit range and the length of the part it decides.
    struct Rule: Sendable {
        var lower: Int
        var upper: Int
        var length: Int
    }

    /// "978" → group lengths.
    let prefixes: [String: [Rule]]
    /// "978-3" → registrant lengths.
    let groups: [String: [Rule]]

    static let shared = ISBNHyphenation(prefixes: ISBNRanges.prefixes, groups: ISBNRanges.groups)

    init(prefixes: String, groups: String) {
        self.prefixes = Self.parse(prefixes)
        self.groups = Self.parse(groups)
    }

    /// The parts joined with hyphens. Outside the known ranges it is the
    /// prefix and the other ten digits: "979-0123456789".
    func hyphenate(_ isbn13: String) -> String {
        let digits = Array(isbn13)
        guard digits.count == 13 else { return isbn13 }
        let ean = String(digits[0..<3])
        let fallback = ean + "-" + String(digits[3...])
        let rest = Array(digits[3...])

        guard let groupLength = length(for: rest, in: prefixes[ean]), groupLength < 9 else { return fallback }
        let group = String(rest[0..<groupLength])
        let afterGroup = Array(rest[groupLength...])
        guard let registrantLength = length(for: afterGroup, in: groups[ean + "-" + group]),
              registrantLength < afterGroup.count - 1 else { return fallback }
        let registrant = String(afterGroup[0..<registrantLength])
        let publication = String(afterGroup[registrantLength..<(afterGroup.count - 1)])
        guard let check = afterGroup.last else { return fallback }
        return [ean, group, registrant, publication, String(check)].joined(separator: "-")
    }

    // MARK: Helpers

    /// The rule for the first seven digits, padded with zeros when fewer are left.
    private func length(for digits: [Character], in rules: [Rule]?) -> Int? {
        guard let rules else { return nil }
        let window = String(digits.prefix(7)).padding(toLength: 7, withPad: "0", startingAt: 0)
        guard let value = Int(window) else { return nil }
        return rules.first { $0.lower <= value && value <= $0.upper }?.length
    }

    /// Lines of "978-3 0000000-0299999:2 0300000-0339999:3 …".
    private static func parse(_ text: String) -> [String: [Rule]] {
        var table: [String: [Rule]] = [:]
        for line in text.split(separator: "\n") {
            let fields = line.split(separator: " ")
            guard let key = fields.first else { continue }
            table[String(key)] = fields.dropFirst().compactMap { field in
                let parts = field.split(separator: ":")
                guard parts.count == 2, let length = Int(parts[1]) else { return nil }
                let bounds = parts[0].split(separator: "-")
                guard bounds.count == 2, let lower = Int(bounds[0]), let upper = Int(bounds[1]) else { return nil }
                return Rule(lower: lower, upper: upper, length: length)
            }
        }
        return table
    }
}
